//! Replays `tests/fixtures/strings/oracle.tsv` (generated by
//! `gen_oracle.php` under PHP 8.3 with mbstring) against this crate.
//!
//! Deprecations are not recorded (master adds several that 8.3 lacks).
//! Known, deliberate differences from 8.3 (php-src master behaviour) are
//! listed in `KNOWN_MASTER_DIFFS`.
#![allow(
    clippy::too_many_lines,
    clippy::match_same_arms,
    clippy::only_used_in_recursion,
    clippy::format_push_string,
    clippy::default_trait_access,
    clippy::many_single_char_names
)]

mod common;
use common::{dispatch, i, parse, s, unhex, V};
use php_mbstring::MbState;
use std::fmt::Write as _;

/// Cases where php-src master intentionally differs from PHP 8.3.
fn known_master_diff(f: &str, a: &[V]) -> bool {
    let enc = a.last().and_then(|v| {
        if let V::S(x) = v {
            Some(x.as_slice())
        } else {
            None
        }
    });
    match f {
        // master's mb_strcut uses mb_cut_gb18030 / mb_cut_utf16* (with its
        // ineffective surrogate check) / mb_cut_utf8 (backs up over
        // continuation bytes even in invalid strings), and returns "" when
        // the computed length is 0.
        "mb_strcut" => {
            let len0 = match (&a[0], &a[1], a.get(2)) {
                (V::S(x), V::I(from), Some(V::I(len))) if *len < 0 => {
                    let l = i64::try_from(x.len()).unwrap();
                    let from = if *from < 0 { (l + from).max(0) } else { *from };
                    (l - from) + len <= 0
                }
                _ => false,
            };
            len0 || matches!(
                enc,
                Some(b"GB18030" | b"UTF-16" | b"UTF-16LE" | b"UTF-16BE")
            ) || (enc == Some(b"UTF-8") && std::str::from_utf8(s(&a[0])).is_err())
        }
        // 8.3 moved the search window by the needle's *byte* length.
        "mb_strrpos" => i(&a[2]) < 0 && enc != Some(b"UTF-8"),
        // master emits no space between adjacent encoded words.
        "mb_decode_mimeheader" => true,
        // master: "must not be empty"; 8.3: "must be a non-empty string".
        "mb_str_pad" => true,
        // master adds GB18030-2022.
        "mb_list_encodings" => true,
        _ => false,
    }
}

fn show(v: &V) -> String {
    match v {
        V::S(b) => format!("{:?}", String::from_utf8_lossy(b)),
        other => format!("{other:?}"),
    }
}

#[test]
fn replay_string_function_oracle() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/strings/oracle.tsv"
    );
    let data = std::fs::read_to_string(path).expect("fixture");
    let mut st = MbState::new();
    let mut failures = String::new();
    let mut nfail = 0usize;
    let mut total = 0usize;
    let mut per_func: std::collections::BTreeMap<String, usize> = Default::default();
    for (lineno, line) in data.lines().enumerate() {
        let parts: Vec<&str> = line.split('\t').collect();
        let f = parts[0];
        let eq = parts.iter().position(|p| p.starts_with('=')).unwrap();
        let args: Vec<V> = parts[1..eq]
            .iter()
            .filter(|p| !p.is_empty())
            .map(|p| parse(p))
            .collect();
        let args = if parts[1..eq].len() == 1 && parts[1].is_empty() {
            vec![]
        } else {
            args
        };
        let expected = parse(&parts[eq][1..]);
        let exp_diag: Vec<String> = parts
            .get(eq + 1)
            .filter(|d| !d.is_empty())
            .map(|d| {
                d.split(',')
                    .map(|h| String::from_utf8(unhex(h)).unwrap())
                    .collect()
            })
            .unwrap_or_default();
        total += 1;
        let got = dispatch(&mut st, f, &args);
        let got_diag: Vec<String> = st
            .take_diagnostics()
            .into_iter()
            .filter(|d| d.level != php_mbstring::Level::Deprecated)
            .map(|d| d.message)
            .collect();
        if (got != expected || got_diag != exp_diag) && !known_master_diff(f, &args) {
            nfail += 1;
            *per_func.entry(f.to_string()).or_default() += 1;
            if nfail <= 40 {
                let _ = writeln!(
                    failures,
                    "line {}: {f}({}) => expected {} {exp_diag:?}, got {} {got_diag:?}",
                    lineno + 1,
                    args.iter().map(show).collect::<Vec<_>>().join(", "),
                    show(&expected),
                    show(&got)
                );
            }
        }
    }
    assert!(
        nfail == 0,
        "{nfail}/{total} oracle mismatches {per_func:?}:\n{failures}"
    );
}
